// =========================================================================
// MESIN OTOMASI MYSIMS (LOGIN + MULTIPART UPLOAD PDF + SCRAPE NOMOR SURAT)
// =========================================================================

const webhookData = $('Webhook Trigger').first().json.body || $('Webhook Trigger').first().json || {};
const cutiId = webhookData.cuti_id || '';
const namaPegawai = webhookData.nama_pegawai || 'Pegawai';
const jenisCuti = webhookData.jenis_cuti || 'Tahunan';
const callbackUrl = webhookData.callback_url || '';
const secretKey = webhookData.secret_key || 'TRANSKEP_WA_BOT_2026';

const mysims = webhookData.mysims_payload || {};
const dari = mysims.dari || namaPegawai;
const uraian = mysims.uraian || ('Permohonan Cuti ' + jenisCuti + ' a.n. ' + namaPegawai);
const kode = mysims.kode || 'KP5.3';
const tglSurat = mysims.tgl_surat || new Date().toISOString().slice(0, 10);
const ket = mysims.ket || ('cuti ' + jenisCuti.toLowerCase());

const pdfBase64 = webhookData.pdf_base64 || '';
const cleanFirst = String(dari).replace(/[^a-zA-Z0-9]/g, ' ').trim().split(/\s+/)[0].toLowerCase();
const pdfFileName = webhookData.pdf_filename || ('TRANSKEP_' + cleanFirst + '_ct.pdf');

let sessionCookie = '';
let nomorSurat = '';
let debugLog = [];

// -------------------------------------------------------------------------
// LANGKAH 1: LOGIN KE MYSIMS (Menangkap Cookie ci_session)
// -------------------------------------------------------------------------
debugLog.push('1. Mengirim login ke MYSIMS...');
try {
  const loginBody = 'u=' + encodeURIComponent('ketua') + '&p=' + encodeURIComponent('admin') + '&ta=' + encodeURIComponent('2026');
  const loginResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://192.168.188.10/mysim/index.php/admin/do_login',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
    },
    body: loginBody,
    disableFollowRedirect: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  const headers = loginResp.headers || {};
  const rawCookies = headers['set-cookie'] || [];
  const list = Array.isArray(rawCookies) ? rawCookies : (rawCookies ? [rawCookies] : []);
  const cookieParts = list.map(c => String(c).split(';')[0].trim()).filter(Boolean);
  sessionCookie = cookieParts.join('; ');
  debugLog.push('Login selesai. Status: ' + (loginResp.statusCode || loginResp.status) + ', Cookie: ' + (sessionCookie ? 'ADA' : 'KOSONG'));
} catch (errLogin) {
  debugLog.push('Login error: ' + errLogin.message);
}

// -------------------------------------------------------------------------
// LANGKAH 1.5: SCRAPE FORM TAMBAH SURAT (Deteksi Field Sifat & File Upload)
// -------------------------------------------------------------------------
let sifatFieldName = 'sifat';
let sifatVal = 'Biasa';
let fileFieldName = 'file_surat';

try {
  const formResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar/add',
    headers: {
      'Cookie': sessionCookie,
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
    },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  const htmlForm = String(formResp.body || formResp.data || '');

  // 1. Deteksi dropdown Sifat
  const selectMatch = htmlForm.match(/<select[^>]*name=["']([^"']*sifat[^"']*)["'][^>]*>([\s\S]*?)<\/select>/i);
  if (selectMatch) {
    sifatFieldName = selectMatch[1];
    const optionsHtml = selectMatch[2];
    const optMatch = optionsHtml.match(/<option[^>]*value=["']([^"']*)["'][^>]*>\s*Biasa\s*<\/option>/i);
    if (optMatch && optMatch[1] !== undefined) {
      sifatVal = optMatch[1];
    }
    debugLog.push('Sifat terdeteksi: field=' + sifatFieldName + ', value=' + sifatVal);
  } else {
    debugLog.push('Sifat default: field=' + sifatFieldName + ', value=' + sifatVal);
  }

  // 2. Deteksi field input File
  const fileMatch = htmlForm.match(/<input[^>]*type=["']file["'][^>]*name=["']([^"']+)["']/i);
  if (fileMatch && fileMatch[1]) {
    fileFieldName = fileMatch[1];
    debugLog.push('Field file terdeteksi: ' + fileFieldName);
  }
} catch (errScrape) {
  debugLog.push('Notice deteksi form: ' + errScrape.message);
}

// -------------------------------------------------------------------------
// LANGKAH 2: SUBMIT FORMULIR SURAT KELUAR MYSIMS (MULTIPART FORM + FILE PDF)
// -------------------------------------------------------------------------
debugLog.push('2. Mengirim formulir surat keluar (multipart)...');
try {
  const boundary = '----n8nFormBoundary' + Math.random().toString(36).substring(2);
  const parts = [];

  const formFields = {
    idp: '',
    no_agenda: '',
    dari: dari,
    no_surat: 'KPA.W10-A2/',
    uraian: uraian,
    kode: kode,
    tgl_surat: tglSurat,
    [sifatFieldName]: sifatVal,
    sifat: sifatVal,
    ket: ket,
    submit: 'Simpan',
    simpan: 'Simpan'
  };

  for (const [key, val] of Object.entries(formFields)) {
    parts.push(Buffer.from(
      '--' + boundary + '\r\n' +
      'Content-Disposition: form-data; name="' + key + '"\r\n\r\n' +
      val + '\r\n'
    ));
  }

  // Lampirkan file PDF Cuti jika ada Base64 dari TRANSKEP
  if (pdfBase64 && pdfBase64.length > 50) {
    const pdfBuffer = Buffer.from(pdfBase64, 'base64');
    parts.push(Buffer.from(
      '--' + boundary + '\r\n' +
      'Content-Disposition: form-data; name="' + fileFieldName + '"; filename="' + pdfFileName + '"\r\n' +
      'Content-Type: application/pdf\r\n\r\n'
    ));
    parts.push(pdfBuffer);
    parts.push(Buffer.from('\r\n'));
    debugLog.push('PDF terlampir: ' + pdfFileName + ' (' + pdfBuffer.length + ' bytes)');
  } else {
    // Kirim part kosong jika tidak ada PDF
    parts.push(Buffer.from(
      '--' + boundary + '\r\n' +
      'Content-Disposition: form-data; name="' + fileFieldName + '"; filename=""\r\n' +
      'Content-Type: application/octet-stream\r\n\r\n\r\n'
    ));
    debugLog.push('File PDF kosong');
  }

  parts.push(Buffer.from('--' + boundary + '--\r\n'));
  const bodyBuffer = Buffer.concat(parts);

  const addResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar/act_add',
    headers: {
      'Cookie': sessionCookie,
      'Content-Type': 'multipart/form-data; boundary=' + boundary,
      'Content-Length': bodyBuffer.length,
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
    },
    body: bodyBuffer,
    disableFollowRedirect: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  debugLog.push('Submit surat status: ' + (addResp.statusCode || addResp.status));
} catch (errSubmit) {
  debugLog.push('Submit error: ' + errSubmit.message);
}

// -------------------------------------------------------------------------
// LANGKAH 3: AMBIL DAFTAR SURAT KELUAR TERBARU & EKSTRAK NOMOR SURAT
// -------------------------------------------------------------------------
debugLog.push('3. Mengambil halaman daftar surat keluar...');
try {
  const listResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar',
    headers: {
      'Cookie': sessionCookie,
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
    },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  const htmlContent = String(listResp.body || listResp.data || listResp || '');
  const regex = /(\d+\/KPA\.W10-A2\/[A-Za-z0-9.]+\/[IVXLCDM]+\/\d{4})/i;
  const match = htmlContent.match(regex);
  if (match && match[1]) {
    nomorSurat = match[1].trim();
    debugLog.push('BERHASIL! Nomor surat ditemukan: ' + nomorSurat);
  } else {
    debugLog.push('Regex belum menemukan nomor surat pada tabel MYSIMS.');
  }
} catch (errList) {
  debugLog.push('Ambil list error: ' + errList.message);
}

return [{
  json: {
    cuti_id: cutiId,
    nomor_surat: nomorSurat,
    secret_key: secretKey,
    callback_url: callbackUrl,
    nama_pegawai: namaPegawai,
    debug_log: debugLog.join(' | ')
  }
}];
